using System;
using System.IO;
using System.Collections.Generic;
using System.Web.Script.Serialization;
public static class SodaDesktopSigninUpgradeChecks {
 const string Owner="S-1-5-21-1-2-3-1001";
 static void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);}
 static void Refused(Action action,string message){bool failed=false;try{action();}catch(InvalidOperationException){failed=true;}catch(IOException){failed=true;}Check(failed,message);}
 sealed class Calls:SodaDesktopSigninUpgradeScm.Calls {
  internal bool Disabled,StoppedValue=true;internal int Disables,Manuals;internal Action OnDisable=null,OnManual=null;
  public void InspectManual(){Check(!Disabled,"Generated manual policy missing");}public void InspectDisabled(){Check(Disabled,"Generated disabled policy missing");}public bool Stopped(){return StoppedValue;}
  public void Disable(){Disables++;Disabled=true;if(OnDisable!=null)OnDisable();}public void Manual(){Manuals++;Disabled=false;if(OnManual!=null)OnManual();}public void Dispose(){}
 }
 sealed class Fixture:IDisposable {
  internal readonly string Root,Source,OldHash,NewHash;internal readonly SodaDesktopSigninInstallFiles.Paths Paths;internal readonly Calls Calls=new Calls();internal bool Active=true;internal int CreatedInitial;
  internal Fixture(bool complete=false,bool observed=true){Root=Path.Combine(Path.GetTempPath(),"soda-upgrade-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Root);Paths=new SodaDesktopSigninInstallFiles.Paths(Path.Combine(Root,"program"),Path.Combine(Root,"data"),Owner,Guid.NewGuid().ToString("N"));OldHash=SodaDesktopSigninInstallSourceChecks.Make(Paths.Code);Source=Path.Combine(Root,"source");NewHash=SodaDesktopSigninInstallSourceChecks.Make(Source);foreach(string name in new[]{"runtime","admin","runs"})Directory.CreateDirectory(Path.Combine(Paths.Slot,name));File.WriteAllBytes(Path.Combine(Paths.Slot,"quiescence.lock"),new byte[]{83});File.WriteAllText(Path.Combine(Paths.Slot,"runtime","identity-keep"),"generated identity sentinel");File.WriteAllText(Path.Combine(Paths.Slot,"enrollment.dpapi"),"generated enrollment sentinel");
   using(var pin=Barrier())using(var exclusive=pin.Exclusive()){var initial=Make("initial",Guid.NewGuid().ToString("D"),exclusive.Fingerprint,null);using(var journal=Journal(SodaDesktopSigninRunJournal.Role.Installer,exclusive.Fingerprint))journal.Initialize(initial);
    if(complete){string id=Guid.NewGuid().ToString("D");var intent=Make("intent",id,exclusive.Fingerprint,null);using(var controller=Journal(SodaDesktopSigninRunJournal.Role.Controller,exclusive.Fingerprint))controller.Prepare(intent);var started=Make("started",id,exclusive.Fingerprint,intent.Digest());using(var host=Journal(SodaDesktopSigninRunJournal.Role.Host,exclusive.Fingerprint)){host.Claim(x=>true);host.Started(started);}using(var observer=Journal(SodaDesktopSigninRunJournal.Role.Observer,exclusive.Fingerprint))observer.Observation(Make("observation",id,exclusive.Fingerprint,started.Digest()));var stopped=Make("stopped",id,exclusive.Fingerprint,started.Digest());using(var host=Journal(SodaDesktopSigninRunJournal.Role.Host,exclusive.Fingerprint))host.Stopped(stopped);if(observed)using(var controller=Journal(SodaDesktopSigninRunJournal.Role.Controller,exclusive.Fingerprint))controller.ObservedStop(Make("observed-stop",id,exclusive.Fingerprint,stopped.Digest()));}
   }
  }
  SodaDesktopSigninRunRecord Make(string kind,string run,string barrier,string digest){var f=new Dictionary<string,object>{{"version",1},{"purpose","desktop-signin-run"},{"kind",kind},{"ownerSid",Owner},{"runId",run},{"packageSha256",OldHash},{"barrierSha256",barrier}};if(kind=="initial")f.Add("createdAt",10000);else if(kind=="intent"){f.Add("issuedAt",10000);f.Add("expiresAt",310000);f.Add("mode","normal");}else{f.Add("pid",1234);f.Add("createdFiletime","134000000000000000");if(kind=="started"){f.Add("startedAt",10001);f.Add("intentSha256",digest);}else if(kind=="observation")f.Add("startedSha256",digest);else if(kind=="stopped"){f.Add("stoppedAt",11000);f.Add("startedSha256",digest);f.Add("nodeExitCode",0);f.Add("jobEmpty",true);}else{f.Add("observedAt",11001);f.Add("stoppedSha256",digest);f.Add("processExitCode",0);f.Add("scmExitCode",0);f.Add("scmSpecificCode",0);f.Add("scmState","stopped");f.Add("barrierExclusive",true);}}return SodaDesktopSigninRunRecord.Build(f,Owner);}
  internal SodaDesktopSigninRunJournal Journal(SodaDesktopSigninRunJournal.Role role,string barrier){return new SodaDesktopSigninRunJournal(Path.Combine(Paths.Slot,"runs"),Owner,OldHash,barrier,role,()=>Active,acl=>true,new string[0]);}
  internal SodaDesktopSigninQuiescence.Pin Barrier(){return SodaDesktopSigninQuiescence.OpenCore(Path.Combine(Paths.Slot,"quiescence.lock"),new[]{Paths.Slot},(p,a)=>true);}
  internal IDictionary<string,object> Run(Action<string> afterStep=null){using(var release=SodaDesktopSigninInstallSource.Open(Source,Owner,NewHash))using(var scm=new SodaDesktopSigninUpgradeScm(Calls,()=>Active))return SodaDesktopSigninUpgrade.Core(Owner,OldHash,release,Paths,scm,()=>Active,Barrier,(p,a)=>true,p=>{Check(SodaDesktopSigninPackageNative.Absent(p),"Generated directory adopted");Directory.CreateDirectory(p);},p=>{if(Path.GetFileName(p)=="initial.writing")CreatedInitial++;return new FileStream(p,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None);},afterStep);}
  internal void Pending(){using(var pin=Barrier())using(var exclusive=pin.Exclusive())using(var writer=Journal(SodaDesktopSigninRunJournal.Role.Controller,exclusive.Fingerprint))writer.Prepare(Make("intent",Guid.NewGuid().ToString("D"),exclusive.Fingerprint,null));}
  internal void Preserved(){Check(File.ReadAllText(Path.Combine(Paths.Slot,"runtime","identity-keep"))=="generated identity sentinel"&&File.ReadAllText(Path.Combine(Paths.Slot,"enrollment.dpapi"))=="generated enrollment sentinel","Upgrade changed identity/enrollment");}
  public void Dispose(){Calls.Dispose();Directory.Delete(Root,true);}
 }
 public static void Run(){
  foreach(bool complete in new[]{false,true})using(var f=new Fixture(complete)){string barrier,expectedRun=null;using(var pin=f.Barrier())barrier=pin.Fingerprint;var result=f.Run(step=>{if(step=="initial-written"){var marker=(Dictionary<string,object>)new JavaScriptSerializer().DeserializeObject(File.ReadAllText(Path.Combine(f.Paths.Slot,"install.transition")));Check(marker.Count==17&&(string)marker["stageName"]==Path.GetFileName(f.Paths.Stage),"Closed upgrade marker lost stage binding");expectedRun=(string)marker["newRunId"];}});Check((string)result["state"]=="upgraded"&&!(bool)result["started"]&&f.Calls.Disables==1&&f.Calls.Manuals==1&&f.CreatedInitial==1,"Upgrade did not commit without starting");f.Preserved();using(var source=SodaDesktopSigninInstallSource.Open(f.Paths.Code,Owner,f.NewHash))Check(source.Current(),"New fixed package missing");using(var source=SodaDesktopSigninInstallSource.Open((string)result["codeArchive"],Owner,f.OldHash))Check(source.Current(),"Old package archive missing");using(var pin=f.Barrier()){Check(pin.Fingerprint==barrier,"Upgrade replaced immutable barrier");using(var journal=new SodaDesktopSigninRunJournal(Path.Combine(f.Paths.Slot,"runs"),Owner,f.NewHash,barrier,SodaDesktopSigninRunJournal.Role.Reader,()=>true,acl=>true,new string[0]))Check(journal.State()=="initial"&&journal.CleanBoundary().RunId==expectedRun,"New package generation not bound to marker");using(var journal=new SodaDesktopSigninRunJournal((string)result["runArchive"],Owner,f.OldHash,barrier,SodaDesktopSigninRunJournal.Role.Reader,()=>true,acl=>true,new string[0]))Check(journal.State()==(complete?"complete":"initial"),"Old clean evidence archive changed");}Check(!File.Exists(Path.Combine(f.Paths.Slot,"install.transition")),"Committed marker retained");}
  using(var f=new Fixture()){f.Calls.StoppedValue=false;Refused(()=>f.Run(),"Running service upgraded");Check(f.Calls.Disables==0&&f.Calls.Manuals==0,"Running service changed");f.Preserved();}
  using(var f=new Fixture()){File.WriteAllText(Path.Combine(f.Paths.Slot,"admin","admin.pending"),"preserve");Refused(()=>f.Run(),"Pending admin upgraded");Check(f.Calls.Disables==0,"Pending admin changed service");f.Preserved();}
  using(var f=new Fixture()){File.WriteAllText(Path.Combine(f.Paths.Slot,"install.transition"),"unknown");Refused(()=>f.Run(),"Unknown marker upgraded");Check(File.ReadAllText(Path.Combine(f.Paths.Slot,"install.transition"))=="unknown"&&f.Calls.Disables==0,"Unknown marker changed");}
  using(var f=new Fixture()){File.Delete(Path.Combine(f.Paths.Slot,"runs","initial"));Refused(()=>f.Run(),"Missing clean evidence upgraded");Check(f.Calls.Disables==0&&f.CreatedInitial==0,"Missing evidence created new initial");}
  using(var f=new Fixture(true,false)){Refused(()=>f.Run(),"Unobserved stopped generation upgraded");Check(f.Calls.Disables==0&&f.CreatedInitial==0&&File.Exists(Path.Combine(f.Paths.Code,"signin-package.json")),"Unobserved stopped generation changed");}
  using(var f=new Fixture()){f.Pending();Refused(()=>f.Run(),"Pending generation upgraded");Check(f.Calls.Disables==0&&f.CreatedInitial==0,"Pending generation changed");}
  using(var f=new Fixture()){File.WriteAllText(Path.Combine(f.Paths.Slot,"runs","unknown"),"preserve");Refused(()=>f.Run(),"Unknown journal upgraded");Check(f.Calls.Disables==0&&f.CreatedInitial==0,"Unknown journal changed generation");}
  using(var f=new Fixture()){f.Calls.OnDisable=()=>f.Active=false;Refused(()=>f.Run(),"Revoked disabled upgrade continued");Check(f.Calls.Disabled&&f.Calls.Manuals==0&&File.Exists(Path.Combine(f.Paths.Code,"signin-package.json")),"Revoked upgrade changed old code");f.Preserved();}
  using(var f=new Fixture()){f.Calls.OnDisable=()=>File.WriteAllText(Path.Combine(f.Paths.Slot,"install.transition"),"unknown");Refused(()=>f.Run(),"Late foreign marker overwritten");Check(f.Calls.Disabled&&f.Calls.Manuals==0&&File.ReadAllText(Path.Combine(f.Paths.Slot,"install.transition"))=="unknown","Late foreign marker changed");}
  using(var f=new Fixture())using(var pin=f.Barrier()){Refused(()=>f.Run(),"Concurrent barrier upgraded");Check(f.Calls.Disables==0,"Concurrent barrier changed service");}
  using(var f=new Fixture())using(var pin=f.Barrier())using(var exclusive=pin.Exclusive())using(var files=new SodaDesktopSigninUpgradeFiles(f.Paths,Guid.NewGuid().ToString("N"),()=>true,(p,a)=>true,p=>Directory.CreateDirectory(p),p=>new FileStream(p,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None))){files.CreateStage();SodaDesktopSigninRunRecord boundary;using(var journal=f.Journal(SodaDesktopSigninRunJournal.Role.Reader,exclusive.Fingerprint))boundary=journal.CleanBoundary();files.Mark(Owner,f.OldHash,f.NewHash,exclusive.Fingerprint,"initial",boundary);Directory.Move(f.Paths.Code,Path.Combine(f.Root,"retained-code"));Directory.CreateDirectory(f.Paths.Code);Refused(()=>files.Move(f.Paths.Code,files.CodeArchive,files.OldCode),"Replaced directory identity was archived");Check(!Directory.Exists(files.CodeArchive),"Replaced directory reached archive");}
  foreach(string step in new[]{"code-archived","runs-archived"})using(var f=new Fixture(true)){Refused(()=>f.Run(at=>{if(at==step)f.Active=false;}),"Interrupted archive upgrade resumed");Check(f.Calls.Disabled&&f.Calls.Manuals==0&&f.CreatedInitial==0&&File.Exists(Path.Combine(f.Paths.Slot,"install.transition")),"Interrupted archive lost disabled recovery state");string[] archives=Directory.GetDirectories(f.Paths.ProgramParent,".signin-old-*");Check(archives.Length==1,"Interrupted archive lost old code");using(var old=SodaDesktopSigninInstallSource.Open(archives[0],Owner,f.OldHash))Check(old.Current(),"Interrupted old package changed");if(step=="runs-archived"){var runs=Directory.GetDirectories(f.Paths.Slot,"runs-old-*");Check(runs.Length==1&&!Directory.Exists(Path.Combine(f.Paths.Slot,"runs")),"Interrupted archive created new generation");using(var pin=f.Barrier())using(var journal=new SodaDesktopSigninRunJournal(runs[0],Owner,f.OldHash,pin.Fingerprint,SodaDesktopSigninRunJournal.Role.Reader,()=>true,acl=>true,new string[0]))Check(journal.State()=="complete","Interrupted old clean journal changed");}f.Preserved();}
  var calls=new Calls();using(var scm=new SodaDesktopSigninUpgradeScm(calls,()=>true)){Refused(()=>scm.Disable(()=>false),"Unproved state disabled service");Check(calls.Disables==0,"Unproved state reached disable");}
  calls=new Calls();using(var scm=new SodaDesktopSigninUpgradeScm(calls,()=>true)){scm.Disable(()=>true);Refused(()=>scm.Manual(()=>false),"Uncommitted state enabled service");Check(calls.Manuals==0,"Uncommitted state reached manual");}
  Console.WriteLine("signin_upgrade_generated_initial_complete_preserved_archives_barrier_and_no_reset_passed");
 }
